    <div style="background: linear-gradient(135deg, rgba(15, 23, 42, 0.85) 0%, rgba(30, 41, 59, 0.75) 100%); border: 1px solid rgba(236, 72, 153, 0.35); border-left: 5px solid #ec4899; border-radius: 12px; padding: 18px 20px; margin-bottom: 24px; box-shadow: 0 8px 24px rgba(0,0,0,0.3);">
