    <!-- DETAIL DETAIL 1: STRUKTUR PROYEK & KONTEN FILE -->
    <div style="background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.07); border-radius: 10px; padding: 18px; margin-bottom: 20px;">
        <h4 style="font-size: 14.5px; font-weight: 700; color: #38bdf8; margin: 0 0 8px 0; display: flex; align-items: center; gap: 8px;">
            <i class="fa-solid fa-folder-tree"></i> 1. Struktur Direktori Proyek Mobile Standar Industri
