        <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 10px; gap: 8px; flex-wrap: wrap;">
            <div>
                <h4 style="font-size: 14.5px; font-weight: 700; color: #38bdf8; margin: 0 0 4px 0; display: flex; align-items: center; gap: 8px;">
                    <i class="fa-solid fa-code"></i> 2. Contoh Kode Sumber Entry Point &amp; Penanganan Layar Sentuh (<code>src/utama.dap</code>)
                </h4>
                <p style="font-size: 12.5px; color: #94a3b8; margin: 0; line-height: 1.45;">
                    Kode ini dieksekusi 60 kali per detik oleh engine Direct GPU. Mengambil koordinat sentuhan sentuh layar secara instan:
                </p>
            </div>
            <button type="button" onclick='loadSnippetToPlayground("/// Contoh Entry Point Mobile DapCode (60 FPS)\nfungsi tombol_sentuh(label: Teks, bx: f64, by: f64, bw: f64, bh: f64, mx: f64, my: f64, ditekan: u64) {\n hover := (mx >= bx && mx <= bx + bw && my >= by && my <= by + bh)\n jika hover && ditekan == 1 {\n kanvas_warna_isi(0.18, 0.88, 0.55, 1.0) // Aksen hijau saat disentuh\n } selain_itu jika hover {\n kanvas_warna_isi(0.12, 0.72, 0.44, 1.0)\n } selain_itu {\n kanvas_warna_isi(0.08, 0.14, 0.24, 0.95)\n }\n // Gambar squircle membulat\n kanvas_persegi_bulat(bx, by, bw, bh, 12.0)\n kanvas_warna_isi(1.0, 1.0, 1.0, 1.0)\n kanvas_teks_tengah(label, bx + bw / 2.0, by + bh / 2.0, 14.0)\n}\n\nfungsi utama() {\n w := kanvas_lebar()\n h := kanvas_tinggi()\n mx := kanvas_mouse_x()\n my := kanvas_mouse_y()\n klik := kanvas_mouse_klik()\n\n // Bersihkan layar & atur latar belakang\n kanvas_bersihkan()\n kanvas_warna_isi(0.04, 0.06, 0.11, 1.0)\n kanvas_persegi(0.0, 0.0, w, h)\n\n // Gambar Status Bar Ponsel\n kanvas_warna_isi(0.06, 0.09, 0.16, 0.95)\n kanvas_persegi(0.0, 0.0, w, 24.0)\n kanvas_warna_isi(1.0, 1.0, 1.0, 0.9)\n kanvas_teks(\"09:41\", 14.0, 16.0, 10.5)\n\n // Kartu Display Glassmorphic\n kanvas_warna_isi(0.08, 0.14, 0.24, 0.95)\n kanvas_persegi_bulat(16.0, 40.0, w - 32.0, 70.0, 14.0)\n kanvas_warna_garis(0.25, 0.65, 0.95, 0.6)\n kanvas_bingkai_persegi_bulat(16.0, 40.0, w - 32.0, 70.0, 14.0)\n kanvas_warna_isi(0.4, 0.9, 1.0, 1.0)\n kanvas_teks_tengah(\"DIRECT GPU 60 FPS\", w / 2.0, 75.0, 15.0)\n\n // Tombol Sentuh Interaktif\n tombol_sentuh(\"Sentuh Layar Saya!\", 20.0, 130.0, w - 40.0, 50.0, mx, my, klik)\n}")' style="background: rgba(56, 189, 248, 0.15); border: 1px solid rgba(56, 189, 248, 0.3); color: #38bdf8; padding: 4px 10px; border-radius: 6px; font-size: 11px; font-weight: 600; cursor: pointer; display: inline-flex; align-items: center; gap: 5px; transition: all 0.2s;" onmouseover="this.style.background='rgba(56,189,248,0.25)'" onmouseout="this.style.background='rgba(56,189,248,0.15)'">
                <i class="fa-solid fa-play" style="font-size: 9px;"></i> Muat ke Playground
