        <pre style="background: #030712; padding: 12px; border-radius: 6px; font-family: 'JetBrains Mono', monospace; font-size: 11.5px; color: #f8fafc; margin: 0; line-height: 1.45; border: 1px solid rgba(56, 189, 248, 0.15); overflow-x: auto; max-width: 100%;"><code>/// src/utama.dap - Siklus Render Layar Sentuh 60 FPS
impor "logika/kalkulator.dap"
impor "ui/komponen.dap"

fungsi utama() {
    w := kanvas_lebar()
    h := kanvas_tinggi()
    mx := kanvas_mouse_x()       // Koordinat X sentuhan jari
    my := kanvas_mouse_y()       // Koordinat Y sentuhan jari
    sentuh := kanvas_mouse_klik() // Status ditekan (1 = aktif, 0 = lepas)

    // 1. Gambar latar belakang gelap elegan
    kanvas_bersihkan()
    kanvas_warna_isi(0.04, 0.06, 0.11, 1.0)
    kanvas_persegi(0.0, 0.0, w, h)

    // 2. Gambar status bar ponsel &amp; jam
    gambar_status_bar(w)

    // 3. Ambil state teks dan riwayat perhitungan
    layar := kanvas_ambil_teks("tampilan")
    riwayat := kanvas_ambil_teks("riwayat")
    gambar_layar_tampilan(w, 40.0, 80.0, riwayat, layar)

    // 4. Render tombol-tombol keypad interaktif
    // (Otomatis mendeteksi koordinat sentuhan &amp; mengubah warna tombol saat ditekan)
}</code></pre>
