                <div style="background: #020617; border: 1px solid rgba(255,255,255,0.08); border-radius: 6px; padding: 10px; font-family: 'JetBrains Mono', monospace; font-size: 11px; color: #cbd5e1; line-height: 1.5; margin-bottom: 8px;">
